// Проверка TypeSafe как реранкера Hindsight: тот же запрос, что строит TypeSafeCrossEncoder._rank_once
// (одна Choice-оценка, варианты = кандидаты), на русских «воспоминаниях» проекта.
const key = process.env.TYPESAFE_API_KEY;
if (!key) { console.log("TYPESAFE_API_KEY: не задан"); process.exit(2); }
console.log("TYPESAFE_API_KEY: задан, длина", key.length);

const query = "Какой сейчас главный вариант стратегии и на каком счёте его считали?";
const docs = [
  "Коллектор стакана работает на сервере 139.99.91.22, пул 76 монет.",
  "Главный вариант (В-104): лонг от старой бид-стены в просадке BTC за 4 часа, трейл 1/1, счёт $2500.",
  "Steam Deck засыпает при разряде — держать на зарядке.",
  "TRX исключён из торгового пула (В-105).",
  "Владелец предпочитает ответы с цифрой в первой строке, время GMT+4.",
  "Прежний кандидат: просадка BTC за 1 час, в августе −$113 на счёте $2500.",
];
const body = {
  state: `Question: ${query}`,
  model: "jev-latest",
  questions: { rank: { type: "choice", instructions: `Which candidate answers the question: ${query}`,
    criteria: Object.fromEntries(docs.map((d, i) => [`c${i}`, d])) } },
};
const t0 = Date.now();
const r = await fetch("https://api.typesafe.ai/v1/systemone", {
  method: "POST",
  headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
  body: JSON.stringify(body),
});
const ms = Date.now() - t0;
const text = await r.text();
console.log("HTTP", r.status, `${ms} мс`);
if (!r.ok) { console.log(text.slice(0, 500)); process.exit(1); }
const j = JSON.parse(text);
const p = j.answers.rank.probabilities;
Object.entries(p).sort((a, b) => b[1] - a[1])
  .forEach(([k, v]) => console.log(v.toFixed(3), docs[+k.slice(1)]));
console.log("model:", j.model ?? "?", "usage:", JSON.stringify(j.usage ?? null));

