const base = "http://127.0.0.1:9077/v1/default/banks/hs-selftest";
const post = async (url, body) => {
  const t0 = Date.now();
  const r = await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  const text = await r.text();
  return { status: r.status, ms: Date.now() - t0, json: (() => { try { return JSON.parse(text); } catch { return text; } })() };
};

if (process.argv[2] === "retain") {
  const r = await post(`${base}/memories`, { async: false, items: [
    { content: "Владелец проекта alpha решил 25.09: главный вариант стратегии — лонг от старой бид-стены в просадке BTC за 4 часа, трейл 1/1, счёт 2500 долларов.", context: "решения владельца" },
    { content: "Steam Deck засыпает при разряде батареи, поэтому его надо держать на зарядке, иначе ночной счёт обрывается.", context: "эксплуатация" },
    { content: "The order book collector runs on server 139.99.91.22 with a pool of 76 coins; sending data to the VPS is disabled.", context: "infrastructure" },
  ] });
  console.log("retain HTTP", r.status, `${(r.ms / 1000).toFixed(1)} с`, JSON.stringify(r.json).slice(0, 300));
} else {
  const qs = [
    "Почему ночной расчёт на приставке оборвался?",
    "Which trading setup did the owner pick as the main one?",
    "Где крутится сборщик стакана и сколько в нём монет?",
  ];
  for (const q of qs) {
    const r = await post(`${base}/memories/recall`, { query: q, budget: "mid", max_tokens: 1024 });
    const res = (r.json.results ?? []).slice(0, 2).map(x => `[${x.type}] ${String(x.text).slice(0, 120)}`);
    console.log(`\nQ: ${q}\n  HTTP ${r.status}, ${r.ms} мс, найдено ${r.json.results?.length ?? "?"}`);
