  const obs = (r.results ?? []).find((x) => x.type === "observation");
  if (obs) {
    const h = await call("GET", `/memories/${obs.id}/history`);
    const items = h.history ?? h.items ?? h;
    console.log(`\nИстория наблюдения (${Array.isArray(items) ? items.length : "?"} версий):`);
    if (Array.isArray(items)) for (const v of items) console.log(`  ${String(v.changed_at || v.created_at || "").slice(0, 16)}  ${String(v.text || v.new_text || v.previous_text || JSON.stringify(v)).slice(0, 150)}`);
  }
} else if (step === "drop") {
  await fetch(B, { method: "DELETE" });
  console.log("тестовая память удалена");
}
